export interface SearchResult {
  datasetId: string;
  name: string;
  description?: string;
  content?: any;
  metadata?: any;
  [key: string]: any;
}

export interface SearchResponse {
  datasets: SearchResult[];
  total?: number;
  page?: number;
  pageSize?: number;
}

class ApiService {
  private baseUrl: string;
  private token: string;

  constructor(baseUrl: string = 'https://cleyrop.com/data-serve/api/v1', token: string = 'black_cake_348230') {
    this.baseUrl = baseUrl;
    this.token = token;
  }

  async search(query: string, page: number = 1, pageSize: number = 10): Promise<SearchResponse> {
    try {
      const headers: Record<string, string> = {};
      if (this.token) {
        headers['TOKEN'] = this.token;
      }

      // First, get all datasets to search through them
      const response = await fetch(`${this.baseUrl}/datasets`, {
        headers
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const allDatasets = await response.json();
      
      // Filter datasets based on search query (client-side filtering since API doesn't have search endpoint)
      const filteredDatasets = allDatasets.filter((dataset: SearchResult) => 
        dataset.name.toLowerCase().includes(query.toLowerCase()) ||
        (dataset.description && dataset.description.toLowerCase().includes(query.toLowerCase()))
      );

      return {
        datasets: filteredDatasets,
        total: filteredDatasets.length,
        page,
        pageSize
      };
    } catch (error) {
      console.error('Search error:', error);
      throw error;
    }
  }

  async getById(datasetId: string): Promise<SearchResult> {
    try {
      const headers: Record<string, string> = {};
      if (this.token) {
        headers['TOKEN'] = this.token;
      }

      const response = await fetch(`${this.baseUrl}/datasets/${datasetId}`, {
        headers
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Get by ID error:', error);
      throw error;
    }
  }

  async getStructuredDataset(datasetId: string): Promise<SearchResult> {
    try {
      const headers: Record<string, string> = {};
      if (this.token) {
        headers['TOKEN'] = this.token;
      }

      const response = await fetch(`${this.baseUrl}/datasets/structured/${datasetId}`, {
        headers
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Get structured dataset error:', error);
      throw error;
    }
  }

  setBaseUrl(url: string) {
    this.baseUrl = url;
  }

  setToken(token: string) {
    this.token = token;
  }
}

export const apiService = new ApiService();
